:root {
  --parchment: #f2e8d5;
  --parchment-dark: #e0cfa8;
  --ink: #2c1f0e;
  --ink-mid: #5a3e20;
  --ink-light: #8b6840;
  --accent-red: #8b1a1a;
  --accent-green: #2a5c2a;
  --accent-gold: #b8860b;
  --accent-gold-light: #d4a82a;
  --panel-bg: #faf4e8;
  --border-dark: #7a5c30;
  --border-light: #c9a96e;
  --stat-bg: #3a2710;
  --stat-text: #f2e8d5;
  --miss-red: #7a1a1a;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
}

.flight-log {
  width: 476px;
  background-color: var(--parchment);
  border: 3px solid var(--border-dark);
  border-radius: 6px;
  overflow: hidden;
  outline: 1px solid var(--border-light);
  outline-offset: -5px;
}

.log-header {
  display: flex;
  align-items: center;
  gap: 8px;
  background-color: var(--stat-bg);
  padding: 8px 12px;
  border-bottom: 3px solid var(--accent-gold);
}

.log-emblem {
  font-size: 24px;
  line-height: 1;
  flex-shrink: 0;
}

.log-title-block {
  display: flex;
  flex-direction: column;
  gap: 1px;
  flex: 1;
}

.log-label {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 1.5px;
  color: var(--accent-gold-light);
  text-transform: uppercase;
}

.log-title {
  font-size: 16px;
  font-weight: 800;
  color: var(--stat-text);
  margin: 0;
  line-height: 1.1;
  letter-spacing: 0.4px;
}

.log-badge {
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 1.5px;
  color: var(--accent-gold);
  border: 2px solid var(--accent-gold);
  border-radius: 4px;
  padding: 3px 6px;
  flex-shrink: 0;
  text-transform: uppercase;
}

.log-body {
  display: flex;
  border-bottom: 2px solid var(--border-light);
}

.raptor-profile {
  flex: 1;
  padding: 7px 12px;
  border-right: 2px solid var(--border-light);
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.profile-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  border-bottom: 1px dashed var(--border-light);
  padding-bottom: 2px;
}

.profile-key {
  font-size: 9px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--ink-light);
}

.profile-val {
  font-size: 11px;
  font-weight: 600;
  color: var(--ink);
}

.flight-stats {
  display: grid;
  grid-template-columns: 1fr 1fr;
  grid-template-rows: 1fr 1fr;
  width: 168px;
  flex-shrink: 0;
}

.stat-cell {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 6px 4px;
  background-color: var(--panel-bg);
  border-left: 1px solid var(--border-light);
  border-bottom: 1px solid var(--border-light);
  gap: 1px;
}

.stat-cell.highlight {
  background-color: var(--accent-gold);
}

.stat-cell.highlight .stat-value {
  color: var(--ink);
}

.stat-cell.highlight .stat-label {
  color: var(--ink-mid);
}

.stat-value {
  font-size: 17px;
  font-weight: 800;
  color: var(--ink);
  line-height: 1;
}

.stat-label {
  font-size: 8px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--ink-light);
}

.flight-runs {
  padding: 6px 12px;
  display: flex;
  flex-direction: column;
  gap: 2px;
  border-bottom: 2px solid var(--border-light);
}

.run-row {
  display: grid;
  grid-template-columns: 26px 60px 52px 1fr;
  align-items: center;
  padding: 3px 4px;
  border-radius: 3px;
  font-size: 11px;
  color: var(--ink);
  font-weight: 500;
}

.run-header-row {
  font-size: 8px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--ink-light);
  border-bottom: 1px solid var(--border-light);
  padding-bottom: 3px;
  margin-bottom: 1px;
  border-radius: 0;
}

.run-num {
  font-weight: 800;
  font-size: 10px;
  color: var(--ink-mid);
}

.result {
  font-size: 10px;
  font-weight: 700;
  border-radius: 3px;
  padding: 1px 5px;
  display: inline-block;
  width: fit-content;
}

.result-ok {
  background-color: var(--accent-green);
  color: #d4f0d4;
}

.result-miss {
  background-color: var(--miss-red);
  color: #f5d4d4;
}

.log-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 5px 12px;
  background-color: var(--parchment-dark);
  border-top: 1px solid var(--border-light);
}

.footer-note {
  font-size: 9px;
  color: var(--ink-mid);
  font-weight: 500;
  letter-spacing: 0.3px;
}

.footer-stamp {
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 2px;
  color: var(--accent-red);
  border: 2px solid var(--accent-red);
  border-radius: 3px;
  padding: 2px 5px;
  text-transform: uppercase;
}
